    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]

    total = v1 + v2 + v3
    result = round(total)

    return {
        "value": result,
        "trace": {
            "v1": v1,
            "v2": v2,
            "v3": v3,
            "sum": total,
            "output_meta": {
                "currency": None,
                "scale": "million",
                "unit": "shares"
            }
        }
    }
